using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierReceipts;public class EditModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public SupplierReceiptForm Item{get;set;}=null!;public SelectList Suppliers{get;private set;}=null!;public SelectList Materials{get;private set;}=null!;public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Update))return Forbid();var x=await db.SupplierReceipts.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=new(){Id=x.Id,SupplierId=x.SupplierId,MaterialId=x.MaterialId,Date=x.Date,PolicyNumber=x.PolicyNumber,Quantity=x.Quantity,UnitPrice=x.UnitPrice,TaxPercent=x.TaxPercent,Details=x.Details};await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Update))return Forbid();if(ModelState.IsValid)try{await transactions.UpdateSupplierReceiptAsync(Item.Id,new(Item.SupplierId,Item.MaterialId,Item.Date,Item.PolicyNumber,Item.Quantity,Item.UnitPrice,Item.TaxPercent,Item.Details));TempData["Message"]="تم تعديل حركة الاستلام";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Suppliers=new(await db.Suppliers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Materials=new(await db.Materials.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}}
